        int[] tests = {121, 10, 12321};
        for (int t : tests) {
            String s = "" + t;
            boolean same = true;
            for (int i = 0; i < s.length(); i++) {
                if (s.charAt(i) != s.charAt(s.length() - 1 - i)) {
                    same = false;
                }
            }
            if (same == true) {
                System.out.println(t + " yes");
            } else {
                System.out.println(t + " no");
            }
        }
    }
}

